    const d=applyDraft(v.data,v.ops,v.imagePreviews),kind=d.pluginId;if(d.sheets)v.sheet=Math.min(v.sheet,d.sheets.length-1);if(d.blocks&&!d.blocks.some(b=>b.index===v.selected))v.selected=d.blocks[0]?.index;v.body.append(el('style',css));
    const run=op=>{const accepted=change(v,op);rerender(v);return accepted!==false;};
    const bindCommit=(input,fn)=>{input.commitDraft=()=>{if(!input.isConnected)return true;if(fn()===false)return false;delete input.dataset.pendingEdit;ctx.controls?.(v);return true;};input.onchange=input.commitDraft;input.oninput=()=>{input.dataset.pendingEdit='true';ctx.controls?.(v);};};
    const syncStyle=style=>{for(const n of v.body.querySelectorAll('[data-style-field]'))n.value=n.dataset.styleField==='fontFamily'?(style?.fontFamily||'Arial'):'#'+(style?.background||'FFFFFF');const number=v.body.querySelector('[aria-label="รูปแบบตัวเลข"]');if(number)number.value=style?.numberFormat||'general';};
